class FrontMiddleBackQueue { private final Deque<Integer> left=new ArrayDeque<>(),right=new ArrayDeque<>();private void balance(){if(left.size()<right.size())left.addLast(right.removeFirst());else if(left.size()>right.size()+1)right.addFirst(left.removeLast());}public FrontMiddleBackQueue(){}public void pushFront(int val){left.addFirst(val);balance();}public void pushMiddle(int val){if(left.size()>right.size())right.addFirst(left.removeLast());left.addLast(val);}public void pushBack(int val){right.addLast(val);balance();}public int popFront(){if(left.isEmpty())return -1;int value=left.removeFirst();balance();return value;}public int popMiddle(){if(left.isEmpty())return -1;int value=left.removeLast();balance();return value;}public int popBack(){if(left.isEmpty())return -1;int value=right.isEmpty()?left.removeLast():right.removeLast();balance();return value;} }
